query:
SELECT category, season, kickoffUtcMs, homeTeam, awayTeam FROM matches WHERE category = 'world_cup' ORDER BY kickoffUtcMs ASC LIMIT 5;
SELECT COUNT(*) as future_count FROM matches WHERE category = 'world_cup' AND kickoffUtcMs > UNIX_TIMESTAMP() * 1000;
SELECT COUNT(*) as total_count FROM matches WHERE category = 'world_cup';

